CX = CY = 256.0
OUTER_R = 226.0
OUTER_STROKE = 17.0
EARTH_R0 = 104.0
EARTH_R = 122.0
EARTH_SCALE = EARTH_R / EARTH_R0
ANGLE_DEG = -70.0
VERTEX_R = 156.0
VISIBLE_INSIDE_R = 90.0

a = math.radians(ANGLE_DEG)
ux, uy = math.cos(a), math.sin(a)
vtop = (CX + VERTEX_R*ux, CY + VERTEX_R*uy)
vbot = (CX - VERTEX_R*ux, CY - VERTEX_R*uy)
entry_inner = (CX + VISIBLE_INSIDE_R*ux, CY + VISIBLE_INSIDE_R*uy)
exit_ = (CX - EARTH_R*ux, CY - EARTH_R*uy)

def wave_path(x1, y1, x2, y2, cycles=5, amp=5.0, steps=96):
    dx, dy = x2-x1, y2-y1
    L = math.hypot(dx, dy)
    nx, ny = -dy/L, dx/L
    pts = []
    for i in range(steps+1):
        t = i/steps
        off = amp*math.sin(2*math.pi*cycles*t)
        pts.append((x1+dx*t+nx*off, y1+dy*t+ny*off))
    return "M " + " L ".join(f"{x:.2f},{y:.2f}" for x,y in pts)

wave_top_start=(284.0,49.0)
wave_bottom_start=(123.0,399.0)
lep_top_end=(396.0,105.0)
lep_bottom_end=(246.0,458.0)

wave_top=wave_path(*wave_top_start,*vtop)
wave_bottom=wave_path(*wave_bottom_start,*vbot)
land_svg="\\n      ".join(f'<path d="{d}"/>' for d in EARTH_PATHS)

svg=f"""<?xml version="1.0" encoding="UTF-8"?>
<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 512 512">
  <metadata>Globe geometry derived from Natural Earth 1:110m data (public domain), orthographic projection centered at 55 E, 15 N.</metadata>
  <defs>
    <clipPath id="earthClip"><circle cx="{CX}" cy="{CY}" r="{EARTH_R}"/></clipPath>
    <marker id="fermionArrow" viewBox="0 0 18 14" refX="17" refY="7"
            markerWidth="18" markerHeight="14" markerUnits="userSpaceOnUse" orient="auto">
      <path d="M 0,0 L 18,7 L 0,14 Z" fill="#000"/>
    </marker>
  </defs>

  <circle cx="{CX}" cy="{CY}" r="{OUTER_R}" fill="none" stroke="#000" stroke-width="{OUTER_STROKE}"/>

  <g id="earth">
    <circle cx="{CX}" cy="{CY}" r="{EARTH_R}" fill="#fff"/>
    <g transform="translate({CX} {CY}) scale({EARTH_SCALE:.8f}) translate({-CX} {-CY})"
       clip-path="url(#earthClip)" fill="#000" fill-rule="evenodd" clip-rule="evenodd">
      {land_svg}
    </g>
    <circle cx="{CX}" cy="{CY}" r="{EARTH_R}" fill="none" stroke="#000" stroke-width="3.8"/>
  </g>

  <g id="feynman-diagram" fill="none" stroke="#000" stroke-linecap="round" stroke-linejoin="round">
    <path d="M {vtop[0]:.2f},{vtop[1]:.2f} L {entry_inner[0]:.2f},{entry_inner[1]:.2f}" stroke-width="4.6"/>
    <path d="M {exit_[0]:.2f},{exit_[1]:.2f} L {vbot[0]:.2f},{vbot[1]:.2f}" stroke-width="4.6"/>
    <path d="{wave_top}" stroke-width="4.8"/>
    <path d="{wave_bottom}" stroke-width="4.8"/>
    <path d="M {vtop[0]:.2f},{vtop[1]:.2f} L {lep_top_end[0]},{lep_top_end[1]}" stroke-width="4.6" marker-end="url(#fermionArrow)"/>
    <path d="M {vbot[0]:.2f},{vbot[1]:.2f} L {lep_bottom_end[0]},{lep_bottom_end[1]}" stroke-width="4.6" marker-end="url(#fermionArrow)"/>
  </g>

  <g fill="#000">
    <circle cx="{vtop[0]:.2f}" cy="{vtop[1]:.2f}" r="9.0"/>
    <circle cx="{vbot[0]:.2f}" cy="{vbot[1]:.2f}" r="9.0"/>
  </g>
</svg>
"""
